			EnvironmentController envController = GameManager.connector.environmentController;
			envController.SetLight(dataModel.GetStageRenderSetting(), PeriodOfDay.Daytime, 0.0f, 0.0f);
			gmsCamera.Setup(dataModel.RenderTexture, dataModel.CalcSpeedUpCoefficient(), envController);
			sceneUI.Setup(dataModel.MaxPutPointNum);
			sceneUI.SetRenderTexture(dataModel.RenderTexture);
			sceneUI.SetTitleLogoSpr(dataModel.GetSpriteByIndex(GraphicTextIndex.TitleLogo_01), dataModel.GetSpriteByIndex(GraphicTextIndex.TitleLogo_02));
			sceneUI.SetSceneBGTexture(bgTexture);
			uiGMSMark.Setup(dataModel.DataContainer.PointDatas);
			uiPointDataList.Setup(dataModel.DataContainer, dataModel.GetStartListIndex(GMSMode.Trade), dataModel.GetStartListIndex(GMSMode.Browsing));
