		private void OnDestroy() {
			if (earthObj != null)
			{
				Destroy(earthObj);
				earthObj = null;
			}
			if (bgTexture != null)
			{
				Resources.UnloadAsset(bgTexture);
				bgTexture = null;
			}
			ResetTradeParam();
			GMSInput.DestroyInstance();
			Sequencer.update -= OnUpdate;
			Sequencer.lateUpdate -= OnLateUpdate;
			resourceLoader.UnloadAssetBundle();
			GMSSoundPlayer.DestroyInstance();
			if (effectEmitter != null)
			{
				effectEmitter.OnFinalize();
				effectEmitter = null;
			}
			uiAchievementAnim.OnFinalize();
			sceneUI.OnFinalize();
			gmsCamera.OnFinalize();
			// GMSMessageWindow.OnFinalize (@01c043f0, placed right after) inlined: msgWindow.OnFinalize(); msgWindow = null
			msgWindow.OnFinalize();
			uiGMSMark.OnFinalize();
			uiPointDataList.OnFinalize();
			dataModel.OnFinalize();
			SwitchNotification.SetFocusHandlingModeSuspend();
		}
		private void ChangeSceneState(global::Dpr.GMS.SceneState nextState) {
			if (dataModel.NowSceneState == nextState)
			{
				GMSWork.EmitLog("Next State is Same State", LogType.Warning);
				return;
			}
			dataModel.SetSceneState(nextState);
			// @01c00790: the 0-caller ChangeSceneState* helpers are inlined into their cases (LaunchAnim, BackTitle,
			// StartGMSModeAnim, Reward, SaveTradeResult); BackTitle's nested ChangeSceneState(ModeSelect) reaches the
			// same-state log through the switch's `break`.
			switch (nextState)
			{
				case SceneState.LaunchAnim:
					ChangeSceneStateLaunchAnim();
					break;
				case SceneState.ModeSelect:
					ChangeSceneStateModeSelect();
					break;
				case SceneState.BackTitle:
					ChangeSceneStateBackTitle();
					break;
				case SceneState.StartGMSModeAnim:
					ChangeSceneStateStartGMSModeAnim();
					break;
				case SceneState.EndGMSModeAnim:
					ChangeSceneStateEndGMSModeAnim();
					break;
				case SceneState.Main:
					ChangeSceneStateMain();
					break;
				case SceneState.Achievement:
					ChangeSceneStateAchievement();
					break;
				case SceneState.Reward:
					ChangeSceneStateReward();
					break;
				case SceneState.SaveTradeResult:
					ChangeSceneStateSaveTradeResult();
					break;
				case SceneState.ConfirmContinue:
					ChangeSceneStateConfirmContinue();
					break;
			}
		}
