			msgWindow.OpenChoiceModeSelectMenu(dataModel.LastSelectModeIndex, select =>
			{
				// <ChangeSceneStateModeSelect>b__65_0 @01c08260
				dataModel.ChangeGMSMode((GMSMode)select);
