			ChangeSceneState(SceneState.OpenBox);
			// GMSSoundPlayer.SetLockPlaySe inlined (+0x20 store)
			GMSSoundPlayer.player.SetLockPlaySe(true);
			sceneUI.HidePutNumText();
			dataModel.OpenBoxWindow(() =>
			{
				// <OpenSelectTradeMonsBox>b__67_0 @01c082c0
				GMSSoundPlayer.player.SetLockPlaySe(false);
				msgWindow.ShowMessage(MessageID.AnnounceTrade, true, null, null, true);
				ChangeSceneState(SceneState.StartGMSModeAnim);
			}, () =>
			{
				// <OpenSelectTradeMonsBox>b__67_1 @01c083f0
				msgWindow.ShowAutoCloseMessage(MessageID.CancelTrade, dataModel.GetAutoCloseMsgTimeShort(), () =>
				{
