			// one test of SelectGMSMode (@01c047d0); both arms inline GMSCamera.ChangeCameraMode (flag 0x4cbd81c ×2)
			if (dataModel.SelectGMSMode == GMSMode.Trade)
			{
				gmsCamera.ChangeCameraMode(CameraMode.TracePoint);
			}
			else
			{
				canControllList = dataModel.CanControllCameraOnBrowsingMode;
				if (canControllList)
					gmsCamera.ChangeCameraMode(CameraMode.TracePoint);
