		private void OnUpdate(float deltaTime) {
			// @01c05190: Sequencer.update target. UpdateStateMain, UpdateSelectReplaceData, UpdateAchievementAnim,
			// UpdateSaveTradeResult, UpdatePenalty and UpdateCamera have 0 callers = inlined into their cases / the tail.
			switch (dataModel.NowSceneState)
			{
				case SceneState.LaunchAnim:
					UpdateStateLaunchAnim();
					break;
				case SceneState.StartGMSModeAnim:
					UpdateStateStartGMSModeAnim(deltaTime);
					break;
				case SceneState.EndGMSModeAnim:
					UpdateStateEndGMSModeAnim();
					break;
				case SceneState.Main:
					UpdateStateMain(deltaTime);
					break;
				case SceneState.BackBox:
					UpdateStateBackBox();
					break;
				case SceneState.NetworkTrade:
					UpdateNetworkTrade(deltaTime);
					break;
				case SceneState.SelectReplaceData:
					UpdateSelectReplaceData();
					break;
				case SceneState.Achievement:
					UpdateAchievementAnim();
					break;
				case SceneState.Reward:
					UpdateReward();
					break;
				case SceneState.SaveTradeResult:
					UpdateSaveTradeResult();
					break;
				case SceneState.Penalty:
					UpdatePenalty();
					break;
			}
			UpdateCamera(deltaTime);
		}
		private void UpdateStateLaunchAnim() {
			if (sceneUI.IsPlayLaunchAnim)
			{
				sceneUI.OnUpdate();
				return;
