			{
				resourceLoader.UnloadAssetBundle();
				ChangeSceneState(SceneState.ModeSelect);
			}
		}
		private void UpdateStateStartGMSModeAnim(float deltaTime) {
			// GMSCamera.IsMoving inlined (0 callers of get_IsMoving @01bfe460)
			if (SmartPoint.Components.Fader.isBusy || gmsCamera.IsMoving)
				return;
			ChangeSceneState(SceneState.Main);
		}
		private void UpdateStateMain(float deltaTime) {
			if (msgWindow.IsOpen)
				return;
			UpdateInput(deltaTime);
			uiPointDataList.OnUpdate();
		}
		private void UpdateInput(float deltaTime) {
			// GMSInput.PushCancel / IsPushPlayCry / OnSpeedUp inlined (flags 0x4cbd843 / 0x847 / 0x846),
			// GMSCamera.IsMoving / RunningRotTween / HasInputMoveSpeed / StopMoveCameraPosition inlined (0 callers each).
			if (GMSInput.PushCancel() && !gmsCamera.IsMoving)
			{
				// CanExitScene (0 callers) inlined: !uiPointDataList.IsShowPointHistoryView (+0x90)
				if (CanExitScene())
				{
					GMSSoundPlayer.player.PlaySeByID(GMSSoundPlayer.PlaySE_ID.BackTop);
					if (dataModel.SelectGMSMode == GMSMode.Trade)
					{
						// BackBoxMenu (0 callers) inlined: OpenSelectTradeMonsBox + ChangeSceneState(BackBox)
						BackBoxMenu();
					}
					else
					{
						dataModel.SetBrowsingListIndex(uiPointDataList.BrowsingPointListIndex);
						ChangeSceneState(SceneState.EndGMSModeAnim);
					}
				}
				return;
			}
			if (uiPointDataList.IsShowPointHistoryView)
				return;
			if (dataModel.SelectGMSMode == GMSMode.Browsing && dataModel.TotalPutPointNum > 0 && GMSInput.IsPushPlayCry())
			{
				int pointIndex = uiPointDataList.SelectPointDataIndex;
				if (pointIndex >= 0)
					GMSSoundPlayer.player.PlayVoice(dataModel.CreatePointMonsVoiceEvent(pointIndex));
			}
			if (dataModel.CanControllCameraOnBrowsingMode && !uiPointDataList.PlayingPointDataList && !gmsCamera.RunningRotTween)
			{
				Vector2 analog = GMSInput.Analog;
				// @01c05e04: `fcmp ; b.ls` → the move arm runs only for sqrMagnitude > 0 (NaN takes the stop arm)
				if (analog.sqrMagnitude > 0.0f)
				{
					if (!gmsCamera.HasInputMoveSpeed)
					{
						uiPointDataList.SetInputEnabled(false);
						uiGMSMark.OnStartMove();
						sceneUI.SetSubkeyguideActive(true);
					}
					// receiver loaded before the Vector2→Vector3 op_Implicit (@01c05e40 / 01c05e74) = one expression
					gmsCamera.MoveCameraPosition(analog, deltaTime, GMSInput.OnSpeedUp());
				}
				else
				{
					gmsCamera.StopMoveCameraPosition();
					if (!gmsCamera.HasInputMoveSpeed)
						sceneUI.SetSubkeyguideActive(false);
				}
			}
		}
		private bool CanExitScene() {
			return !uiPointDataList.IsShowPointHistoryView;
		}
