		private void UpdateCamera(float deltaTime) {
			InputCamera();
			gmsCamera.OnUpdate(deltaTime);
		}
		private void InputCamera() {
			// GMSCamera.CanInput / IsHighZoom and GMSInput.PushNearCamera / PushFarCamera (flags 0x4cbd845 / 0x844) inlined
			if (!gmsCamera.CanInput)
				return;
			if (msgWindow.IsOpen)
				return;
			if (uiManagerPtr.GetCurrentUIWindow<ContextMenuWindow>() != null)
				return;
			if (GMSInput.PushNearCamera())
				gmsCamera.PerformNearDistance();
			else if (GMSInput.PushFarCamera())
				gmsCamera.PerformFarDistance();
			else
				return;
			uiGMSMark.OnChangeDistanceLevel(gmsCamera.IsHighZoom);
		}
		private void OnLateUpdate(float deltaTime) {
			// @01c066a0: GMSCamera.OnLateUpdate (UpdateRot/UpdateMove/UpdatePosition) and CheckTweenRunning inlined (0 callers each)
			gmsCamera.OnLateUpdate(deltaTime);
			// `state < 11 && (0x680 >> state & 1)` = Main / NetworkTrade / SelectReplaceData
			switch (dataModel.NowSceneState)
			{
				case SceneState.Main:
				case SceneState.NetworkTrade:
				case SceneState.SelectReplaceData:
					UpdatePointMark();
					break;
			}
			gmsCamera.CheckTweenRunning();
		}
		private void UpdatePointMark() {
			// GMSCamera.CameraPosition inlined (cameraTransform.localPosition)
			Vector3 cameraNormal = gmsCamera.CameraPosition.normalized;
			GMSPointDataModel[] points = dataModel.DataContainer.PointDatas;
			for (int i = 0; i < points.Length; i++)
			{
				GMSPointDataModel target = points[i];
				// IsHighZoom compared per iteration (@01c05118; LTO hoisted the two level loads)
				dataModel.UpdatePointPosition(target, in cameraNormal, gmsCamera.IsHighZoom);
				uiGMSMark.UpdatePointPosition(i, target);
			}
		}
		private void OnSelectListData(global::Dpr.GMS.PointHistoryDataModel selectData) {
			GMSWork.EmitLog("Change State : SelectListData");
			GMSWork.EmitLog(string.Format("SceneState [{0}] GMSMode [{1}]", dataModel.NowSceneState, dataModel.SelectGMSMode));
			switch (dataModel.NowSceneState)
			{
				case SceneState.SelectReplaceData:
					OpenConfirmReplaceDataMsg();
					break;
				case SceneState.Main:
					if (dataModel.SelectGMSMode == GMSMode.Trade)
					{
						StartTradeFlow();
						break;
					}
					if (!uiPointDataList.IsShowPointHistoryView)
					{
						dataModel.OpenKeyguide(KeyguidePattern.BrowsingHistory);
						break;
					}
					GMSPointDataModel pointData = dataModel.GetPointDataModelByIndex(uiPointDataList.SelectPointDataIndex);
					OpenChoicePointOperationMenu(selectData.DataIndex == pointData.MarkIndex, uiPointDataList.CurrentSelectPointHistoryIndex == 0);
					break;
			}
		}
		private void OpenConfirmReplaceDataMsg() {
			if (uiPointDataList.CurrentSelectPointHistoryIndex == 0)
			{
				// OpenConfirmStayMessage (0 callers) inlined (its flag 0x4cbd83a @01c06aa8)
				OpenConfirmStayMessage();
				return;
			}
			msgWindow.ShowMessage(MessageID.ConfirmReplacePoke, false, () =>
			{
				// <OpenConfirmReplaceDataMsg>b__97_0 @01c08510: GMSMessageWindow.OpenYesNoMenu inlined
				msgWindow.OpenYesNoMenu(select =>
				{
					// <OpenConfirmReplaceDataMsg>b__97_1 @01c085d0
					if (select == 0)
						OnChoiceReplaceData();
					else
						msgWindow.CloseMsgWindow();
				});
			});
		}
		private void JumpPoint(int pointIndex, global::System.Action onMoveEnd) {
			GMSWork.EmitLog(string.Format("JumpPoint : Go Point[{0}]", pointIndex));
			GMSPointDataModel pointData = dataModel.GetPointDataModelByIndex(pointIndex);
			switch (dataModel.SelectGMSMode)
