		private void JumpNearPoint() {
			Vector3 cameraNormal = gmsCamera.CameraPosition.normalized;
			GMSPointDataModel nearPoint = dataModel.FindNearPointDataFromCamera(ref cameraNormal);
			if (nearPoint != null && dataModel.CanSnapPoint())
				JumpPoint(nearPoint.index, null);
		}
		private void OnStopCameraMove() {
			if (!dataModel.CanSnapPoint())
				return;
			Vector3 cameraNormal = gmsCamera.CameraPosition.normalized;
			GMSPointDataModel nearPoint = dataModel.FindNearPointDataFromCamera(ref cameraNormal);
			if (nearPoint == null)
				return;
			if (gmsCamera.CanSnapPoint(in nearPoint.point))
			{
				GMSWork.EmitLog(string.Format("Snap Camera to PointIndex[{0}]", nearPoint.dataIndex));
				// <OnStopCameraMove>b__105_0 @01c08720
				gmsCamera.SnapPoint(nearPoint.index, in nearPoint.point, () => uiPointDataList.SetInputEnabled(true, true, false));
				if (dataModel.SelectGMSMode == GMSMode.Trade)
					uiPointDataList.MoveTradePointListIndex(nearPoint.index);
				else
					uiPointDataList.MoveBrowsingPointListIndex(nearPoint.dataIndex);
				uiGMSMark.OnSelectPoint(nearPoint.index, gmsCamera.IsHighZoom, true);
				sceneUI.SetSubkeyguideActive(false);
			}
			else
			{
				uiPointDataList.SetInputEnabled(true, true, false);
			}
		}
		private void OnReleaseListInput() {
			if (dataModel.SelectGMSMode == GMSMode.Browsing && dataModel.TotalPutPointNum < 2)
				return;
			DecideSelectPoint();
		}
		private void OnCancelList() {
			if (dataModel.SelectGMSMode == GMSMode.Browsing)
			{
				if (uiPointDataList.IsShowPointHistoryView)
					dataModel.OpenKeyguide(KeyguidePattern.Browsing);
				return;
			}
			GMSSoundPlayer.player.PlaySeByID(GMSSoundPlayer.PlaySE_ID.ReplaceCancel);
			// OpenConfirmStayMessage inlined (flag 0x4cbd83a @01c07538)
			OpenConfirmStayMessage();
		}
