		private void DecideSelectPoint() {
			if (!dataModel.CanSnapPoint())
				return;
			// dataModel is re-read after the Trade arm's get_TradePointListIndex call but reused on the inlined
			// SelectPointDataIndex arm (@01c07400..) = one ternary feeding one GetPointDataModelByIndex statement
			int index = dataModel.SelectGMSMode == GMSMode.Trade ? uiPointDataList.TradePointListIndex : uiPointDataList.SelectPointDataIndex;
